fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let code = match args.first().map(String::as_str) {
        Some("serve") => {
            let rt = tokio::runtime::Builder::new_multi_thread().enable_all().build().expect("runtime");
            rt.block_on(relay::serve(args[1..].to_vec()))
        }
        Some("worker") => {
            let rt = tokio::runtime::Builder::new_current_thread().enable_all().build().expect("runtime");
            match rt.block_on(mcp::serve_stdio(types::WorkerOpts::parse(&args[1..]))) {
                Ok(()) => 0,
                Err(e) => {
                    eprintln!("gmnew worker: {e}");
                    1
                }
            }
        }
        _ => cli::main(args),
    };
    std::process::exit(code);
}

#!/usr/bin/env node
// The host's pipe to the gm-new core, tools/core.mjs. The host (Claude Code) starts this file from .mcp.json and holds its stdio. This file
// passes lines both ways, and it does nothing else: it reads where a line ends, never what the line says. The host's lines reach the core
// through a named pipe that this file keeps open for reading and for writing, so a core that exits does not close it, and the lines wait in
// the pipe for the next core. The core's output comes back on its stdout. When that output ends, the core is gone without a handover, and a
// new core starts after RESPAWN_MS. A core that hands over to a newer one keeps the output open, so no second core starts. An error is
// logged, and the connection stays open: this file does not exit on an error. It never changes, so a change to it needs the host to
// reconnect. Everything else is in the core.
import { spawn, spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { constants, createWriteStream, openSync, unlinkSync } from 'node:fs';
import { createInterface } from 'node:readline';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const CORE = join(dirname(fileURLToPath(import.meta.url)), 'core.mjs');
const RESPAWN_MS = 1000;
const EXIT_MS = 10000;
const args = process.argv.slice(2);
// The workspace is the directory the host started this file in, unless the host's arguments name one. An entry with no arguments serves
// the directory it was started in, so one user-level entry serves each project.
if (!args.includes('--workspace')) args.push('--workspace', process.cwd());
let core = null;
let closing = false;

function log(message) {
  process.stderr.write(`gm-new relay: ${message}\n`);
}

// An error in this process is logged, and the connection stays open.
process.on('uncaughtException', (err) => log(`error: ${err?.stack ?? err}`));
process.on('unhandledRejection', (err) => log(`error: ${err?.stack ?? err}`));
process.stdout.on('error', (err) => log(`host output: ${err.message}`));

// The input pipe. The relay holds a reader and a writer, so a write does not fail while no core runs, and the core's end of input comes only
// when this file ends the writer. Node closes a child's stdin when the child exits, so the pipe is not the child's: it is this file's.
const FIFO = join(tmpdir(), `gm-new-${process.pid}-${randomBytes(4).toString('hex')}.in`);
const made = spawnSync('mkfifo', [FIFO]);
if (made.status !== 0) {
  log(`cannot make the input pipe ${FIFO}: ${String(made.stderr || made.error?.message)}`);
  process.exit(1);
}
process.on('exit', () => {
  try {
    unlinkSync(FIFO);
  } catch {
    // The pipe is already gone.
  }
});
const reader = openSync(FIFO, constants.O_RDONLY | constants.O_NONBLOCK);
const input = createWriteStream(FIFO, { fd: openSync(FIFO, 'w') });
input.on('error', (err) => log(`input pipe: ${err.message}`));

function toCore(line) {
  input.write(`${line}\n`);
}

function start() {
  if (closing) return;
  const proc = spawn(process.execPath, [CORE, ...args], { stdio: [reader, 'pipe', 'inherit'] });
  core = proc;
  log(`core started (pid ${proc.pid})`);
  proc.on('error', (err) => log(`core did not start: ${err.message}`));
  proc.on('exit', (code, signal) => log(`core exited (${signal ?? `code ${code}`})`));
  createInterface({ input: proc.stdout, crlfDelay: Infinity })
    .on('line', (line) => {
      if (line.trim() !== '') process.stdout.write(`${line}\n`);
    })
    .on('close', () => {
      log('core output ended');
      if (closing) process.exit(0);
      if (core !== proc) return;
      core = null;
      setTimeout(start, RESPAWN_MS);
    });
}

// The end of the host's input ends the writer. The core reads what is left in the pipe, then its end of input, and it pauses its worker.
function shutdown() {
  if (closing) return;
  closing = true;
  log('host closed the connection; ending the core');
  input.end(() => {
    if (core === null) process.exit(0);
  });
  setTimeout(() => process.exit(0), EXIT_MS).unref();
}

createInterface({ input: process.stdin, crlfDelay: Infinity })
  .on('line', (line) => {
    if (line.trim() !== '') toCore(line);
  })
  .on('close', shutdown);
for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, shutdown);
start();

// Registers the loader hook (src/hot-hook.mjs) and owns the generation counter it reads. The worker imports this module at boot, so the
// hook is in place before the first reload. Until a bump, every module loads at its plain URL, exactly as without the hook.
import { register } from 'node:module';

const shared = new SharedArrayBuffer(4);
const counter = new Int32Array(shared);
register('./hot-hook.mjs', import.meta.url, { data: { generation: shared } });

// Starts a new generation and returns its number. The next import of each reloadable module, from any module under src/, is a fresh instance.
export function bumpGeneration() {
  return Atomics.add(counter, 0, 1) + 1;
}

// The loader hook, run on the loader's own thread. A reloadable module under src/ is loaded at the current generation, through a
// ?gen=N query. The generation is a counter shared with the worker (src/hot.mjs), so a bump makes the next import of each reloadable
// module a fresh instance, and every module that imports it at that generation gets fresh instances too. A singleton keeps its one
// instance, because its URL never changes.
import { RELOADABLE } from './hot-config.mjs';

const SRC = new URL('./', import.meta.url).href;
const reloadable = new Set(RELOADABLE);
let generation = null;

export function initialize(data) {
  generation = new Int32Array(data.generation);
}

export async function resolve(specifier, context, nextResolve) {
  const result = await nextResolve(specifier, context);
  if (generation === null || !result.url.startsWith(SRC)) return result;
  if (!reloadable.has(result.url.slice(SRC.length))) return result;
  const gen = Atomics.load(generation, 0);
  if (gen === 0) return result;
  return { ...result, url: `${result.url}?gen=${gen}`, shortCircuit: true };
}

// The modules under src/ that a running worker reloads in place. A reload replaces their tool definitions, their compaction tables and their
// verb handlers (tools.mjs builds the handlers from the modules the worker passes). No module keeps state at module level; a verb's own index
// (code-ast.mjs) is built again on its next call. Every other module under src/ is a singleton, and a change to it restarts the worker,
// because it holds state that a reload would lose (the log, the jobs, the paging of search results) or it is on the path of every call.
export const RELOADABLE = ['git.mjs', 'rows.mjs', 'fetch.mjs', 'code-ast.mjs', 'wiki-tools.mjs', 'review-tools.mjs'];

// A resolve hook for run_code. Every project file a body loads gets a query that holds the current generation, a counter that run_code
// bumps when a project file changed. Node caches ES modules by URL, so without this a later call would reuse the modules of an earlier
// one, including a file that imports an edited file. With a new generation after each edit, every project file loads as it is on disk.
// Files under node_modules are left alone. The hook runs on Node's loader thread; its root and the shared counter come from the data
// passed to module.register in runcode.mjs.
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { isAbsolute, relative, sep } from 'node:path';

let root = null;
let generation = null;

export function initialize(data) {
  root = data.root;
  generation = new Int32Array(data.buffer);
}

export async function resolve(specifier, context, nextResolve) {
  const result = await nextResolve(specifier, context);
  if (root === null || !result.url.startsWith('file:')) return result;
  const [base] = result.url.split('?');
  const path = fileURLToPath(base);
  const rel = relative(root, path);
  if (rel === '' || rel === '..' || rel.startsWith(`..${sep}`) || isAbsolute(rel)) return result;
  if (rel.split(sep).includes('node_modules') || !existsSync(path)) return result;
  return { ...result, url: `${base}?g=${Atomics.load(generation, 0)}` };
}

