pub fn digest(reply: &Value) -> Value {
    let mut out = Map::new();
    for key in ["ok", "error", "prefixSha", "total"] {
        if let Some(v) = reply.get(key) {
            out.insert(key.into(), v.clone());
        }
    }
    Value::Object(out)
}

