// The rules of an MCP run, one per line, without their numbers.
export function ruleBodies() {
  return MCP_RULES.split('\n').filter((line) => /^\d+\. /.test(line)).map((line) => line.replace(/^\d+\. /, ''));
}

// The skills under skills/, each SKILL.md. A bare name of an unserved tool, that is not written as gm.<name>, is a finding. The gm skill
// holds each rule word for word. The check reads the skill without its gm. prefix, so a verb may be written as gm.query_log.
export function skillCheck(root) {
  const dir = join(root, 'skills');
  if (!existsSync(dir)) return { ok: true, detail: 'no skills' };
  const names = unservedNames();
  const findings = [];
  let count = 0;
  for (const skill of readdirSync(dir)) {
    const file = join(dir, skill, 'SKILL.md');
    if (!existsSync(file)) continue;
    count += 1;
    const text = readFileSync(file, 'utf8');
    for (const name of names) {
      if (new RegExp(`(?<![\\w.])${name}\\b`).test(text)) findings.push(`${skill} names ${name} without gm.`);
    }
    if (skill === 'gm') {
      const plain = text.replace(/\bgm\./g, '');
      for (const rule of ruleBodies()) if (!plain.includes(rule)) findings.push(`gm skill lacks rule: ${rule.slice(0, 60)}`);
    }
  }
  for (const skill of SERVED_SKILLS) {
    try {
      parseSkill(readFileSync(join(dir, skill, 'SKILL.md'), 'utf8'), skill);
    } catch (err) {
      findings.push(err.message);
    }
  }

    out
}

pub fn lint_wiki(root: &Path) -> Lint {
    let dir = root.join("wiki");
    if !dir.exists() {
        return Lint {
            problems: Vec::new(),
            pages: 0,
            claims: 0,
            skipped: true,
        };
    }
    let mut problems: Vec<String> = Vec::new();
    let index_path = dir.join("index.md");
    let log_path = dir.join("log.md");
    if !index_path.exists() {
        problems.push("wiki/index.md is missing".to_string());
    }
    if !log_path.exists() {
        problems.push("wiki/log.md is missing".to_string());
    }
    let index_text = fs::read_to_string(&index_path).unwrap_or_default();
    let log_text = fs::read_to_string(&log_path).unwrap_or_default();
    let mut indexed: Vec<String> = Vec::new();
    let mut indexed_set: HashSet<String> = HashSet::new();
    for row in index_text.split('\n') {
        if let Some(name) = entry_name(row) {
            if indexed_set.insert(name.to_string()) {
                indexed.push(name.to_string());
            }
        }
    }
    let mut files: Vec<String> = fs::read_dir(&dir)
        .map(|entries| {
            entries
                .flatten()
                .map(|e| e.file_name().to_string_lossy().into_owned())
                .filter(|n| n.ends_with(".md") && n != "index.md" && n != "log.md")
                .collect()

        problems,
        pages: pages.len(),
        claims,
        skipped: false,
    }
}

pub fn wiki_check(root: &Path) -> Value {
    let lint = lint_wiki(root);
    if lint.skipped {
        return json!({"ok": true, "detail": "no wiki"});
    }
    if !lint.problems.is_empty() {
        let head: Vec<&str> = lint.problems.iter().take(3).map(String::as_str).collect();
        return json!({
            "ok": false,
            "detail": format!("{} problems: {}", lint.problems.len(), head.join(" | ")),
        });
    }
    json!({
        "ok": true,
        "detail": format!("{} pages, {} claims, lint clean", lint.pages, lint.claims),
    })
}

