const GH_TIMEOUT_MS = 60000;
const CHECK_TIMEOUT_MS = 15000;
const GIT_ENV = { GIT_TERMINAL_PROMPT: '0', GIT_LITERAL_PATHSPECS: '1' };
const MAX_COUNT = 200;
