        ok: true,
        status: response.status,
        bytes: read.bytes,
        finalUrl: current.href,
        redirects,
        source: archived.id,
        sourceNew: archived.created,
        output: `${response.status} ${read.bytes} bytes ${current.href}\n${text}`,
