export function errorTypeOf(result) {
  if (result.ok) return null;
  return transientText(`${result.error ?? ''}\n${result.output ?? ''}`);
}

export function backoffMs(attempt) {
  const base = Math.min(BASE_MS * 2 ** (attempt - 1), CAP_MS);
