const R = '/workspace/gm-new/';
const [a, b, c, d] = await Promise.all([
  gm.grep({ pattern: 'fn confine|fn root_of|fn is_sha|CHECK_TIMEOUT: |fn random_u64|fn run_command|fn fail|fn blocking', root: R + 'rust/src', mode: 'regex', limit: 30 }),
  gm.grep({ pattern: 'export const SHA|export async function commitExists|export function confine|function confine|export function commitExists', root: R + 'src', mode: 'regex', limit: 30 }),
  gm.read_file({ path: R + 'rust/src/git.rs' }),
  gm.list_dir({ path: R + 'src' }),
